import {
  getDesignSystemBySlug,
  loadDesignSystemMarkdown,
} from '../services/templates/designCatalog';
import type {
  ActiveProjectContext,
  ActiveVariantSnapshot,
  DesignContextEntry,
  ProjectContext,
} from './contracts';
import type { VariantDesignSource } from '../services/VariantHistoryService';

export const enrichDesignSource = (
  design: ActiveVariantSnapshot['design'],
): ActiveVariantSnapshot['design'] => {
  if (!design || design.kind !== 'slug') return design;
  return {
    ...design,
    displayName: getDesignSystemBySlug(design.slug)?.name ?? design.slug,
  };
};

export const toActiveProjectContext = (
  projectContext: ProjectContext,
): ActiveProjectContext => {
  const sourceCount =
    projectContext.variantContext?.userContext.filter(
      (source) => source.transport !== 'prompt',
    ).length ?? 0;
  const hasSourceContextSummary = Boolean(
    sourceCount > 0 ||
    (projectContext.variantContext?.rivetMetadata.length ?? 0) > 0,
  );
  const activeSourceContext = hasSourceContextSummary
    ? {
        sourceCount,
        isSourceGrounded: Boolean(
          sourceCount > 0 ||
          projectContext.designContext?.length ||
          projectContext.variantContext?.rivetMetadata.length,
        ),
      }
    : undefined;

  if (projectContext.kind === 'existing') {
    return {
      kind: 'existing',
      designContext: projectContext.designContext?.map((entry) =>
        entry.kind === 'slug'
          ? { kind: 'slug', slug: entry.slug }
          : { kind: 'markdown', label: entry.label },
      ),
      ...(activeSourceContext ? { sourceContext: activeSourceContext } : {}),
    };
  }
  return {
    kind: 'fresh',
    workspacePath: projectContext.workspacePath,
    workspaceRoot: projectContext.workspaceRoot,
    framework: projectContext.framework,
    designContext: projectContext.designContext?.map((entry) =>
      entry.kind === 'slug'
        ? { kind: 'slug', slug: entry.slug }
        : { kind: 'markdown', label: entry.label },
    ),
    ...(activeSourceContext ? { sourceContext: activeSourceContext } : {}),
    ...(projectContext.executionPlan
      ? {
          executionPlan: {
            mode: projectContext.executionPlan.mode,
            confidence: projectContext.executionPlan.confidence,
            reason: projectContext.executionPlan.reason,
            assetCount: projectContext.executionPlan.assetPlan?.length ?? 0,
            runtimeRequirementCount:
              projectContext.executionPlan.runtimeRequirements?.length ?? 0,
          },
        }
      : {}),
  };
};

export const resolveDesignArtifact = (
  entry: DesignContextEntry | undefined,
): { markdown: string; source: VariantDesignSource } | null => {
  if (!entry) return null;
  if (entry.kind === 'markdown') {
    return {
      markdown: entry.content,
      source: { kind: 'markdown', label: entry.label },
    };
  }
  const markdown = loadDesignSystemMarkdown(entry.slug);
  if (!markdown) return null;
  const catalogEntry = getDesignSystemBySlug(entry.slug);
  return {
    markdown,
    source: {
      kind: 'slug',
      slug: entry.slug,
      label: catalogEntry?.name ?? entry.slug,
    },
  };
};
